export function handleCreateTask(store, rawBody) {
  let parsed;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    return { status: 400, body: { error: 'body is not valid JSON' } };
  }
  const title = parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed.title : undefined;
  if (typeof title !== 'string' || title.trim() === '') {
    return { status: 400, body: { error: 'title must be a nonempty string' } };
  }
  let nextId = 1;
  for (const t of store) if (t.id >= nextId) nextId = t.id + 1;
  const task = { id: nextId, title, done: false };
  store.push(task);
  return { status: 201, body: task };
}

